//! Unsealed full SYSTEM_ACCESSOR data over genuine original raw-policy page loans.
use crate::{captured_generator_budget::Budget,captured_reactive_reads::Failure,reactive_raw_policy_pages::RawPolicyPages,system_accessors_policy::{Output,Builder},key_policy_control::Control};
use std::{collections::{BTreeMap,HashMap},io,sync::Arc};
struct Scratch{budget:Arc<Budget>,ok:bool}impl Drop for Scratch{fn drop(&mut self){if !self.ok{self.budget.keep_failed_scratch()}}}
fn oom(budget:&Budget,message:impl Into<String>)->Failure{budget.deny();Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,message.into()))}
fn check(budget:&Budget,poll:&dyn Fn()->io::Result<()>)->Result<(),Failure>{budget.require().map_err(|m|oom(budget,m))?;poll()?;budget.require().map_err(|m|oom(budget,m))}
struct Native<'a>{budget:&'a Budget,poll:&'a dyn Fn()->io::Result<()>}impl Control for Native<'_>{type Error=Failure;const CHECKED:bool=true;fn checkpoint(&mut self)->Result<(),Failure>{check(self.budget,self.poll)}fn reserve(&mut self,n:usize)->Result<(),Failure>{self.budget.charge(n).map_err(|m|oom(self.budget,m))}fn overflow(&mut self)->Failure{oom(self.budget,"System scanner admission overflow")}fn allocation_failed(&mut self)->Failure{self.overflow()}}
fn retained(out:&Output)->Option<usize>{out.diags.iter().try_fold(out.body.capacity().checked_add(out.diags.capacity().checked_mul(std::mem::size_of::<crate::sparse_slots_policy::Diagnostic>())?)?,|n,d|n.checked_add(d.rel.capacity())?.checked_add(d.msg.capacity()))}
/// Unsealed source-only accessor data. The host supplies actual CODE completion.
pub fn generate_from_pages(pages:&dyn RawPolicyPages,order:&HashMap<String,usize>,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>)->Result<Output,Failure>{
 check(root,poll)?;let mut scratch=Scratch{budget:Budget::scoped_temporaries(root).map_err(|m|oom(root,m))?,ok:false};let budget=&scratch.budget;
 let result=(||{
 let rows=crate::reactive_raw_policy_pages::collect_marker_rows(|visit|pages.for_each(visit),order,budget,&["SYSTEM_ACCESSOR"],false,false,false,&mut||check(budget,poll).map_err(|e|match e{Failure::Operational(e)=>e,Failure::Unsupported(m)=>io::Error::other(m)}),&||check(budget,poll))?;
 let mut requested:BTreeMap<String,BTreeMap<String,bool>>=BTreeMap::new();for marker in &rows.markers{check(budget,poll)?;if let(Some(system),Some(key))=(marker.args.first(),marker.args.get(2)){if let Some(var)=key.trim().strip_prefix("nameof(").and_then(|s|s.strip_suffix(')')){let var=var.trim();if !requested.get(system).is_some_and(|vars|vars.contains_key(var)){budget.charge(system.len().checked_add(var.len()).and_then(|n|n.checked_mul(2)).and_then(|n|n.checked_add(4096)).ok_or_else(||oom(budget,"System field directory overflow"))?).map_err(|m|oom(budget,m))?;requested.entry(system.clone()).or_default().insert(var.to_owned(),false);}}}}
 let mut definitions=std::collections::HashSet::new();let complete=pages.for_each(&mut|_,views|{let file_budget=views.allocation_budget(budget);check(file_budget,poll)?;crate::system_accessors_policy::visit_system_defs_using(views.raw()?,&mut||check(file_budget,poll),&mut|groups|file_budget.charge(groups.checked_mul(4).and_then(|n|n.checked_mul(std::mem::size_of::<Option<(usize,usize)>>())).and_then(|n|n.checked_add(std::mem::size_of::<crate::pat::Caps<'_>>()+128)).ok_or_else(||oom(file_budget,"System capture group overflow"))?).map_err(|m|oom(file_budget,m)),&mut|name|{check(budget,poll)?;if !definitions.contains(name){budget.charge(name.len().checked_mul(2).and_then(|n|n.checked_add(2048)).ok_or_else(||oom(budget,"System definition backing overflow"))?).map_err(|m|oom(budget,m))?;definitions.insert(name.to_owned());}Ok(())})?;Ok(true)})?;if !complete{return Err("System definition traversal stopped before exhaustion".into())}
 let mut selectors:Vec<(String,Vec<String>)>=Vec::new();let mut candidates:BTreeMap<String,Vec<usize>>=BTreeMap::new();for name in requested.keys(){check(budget,poll)?;budget.charge(name.len().checked_mul(12).and_then(|n|n.checked_add(4096)).ok_or_else(||oom(budget,"System selector allocation overflow"))?).map_err(|m|oom(budget,m))?;if !budget.row(&mut selectors){return Err(oom(budget,"System selector rows denied"))}let types=crate::system_accessors_policy::system_types(name);let index=selectors.len();for ty in &types{if !candidates.contains_key(ty){budget.charge(ty.len().checked_mul(2).and_then(|n|n.checked_add(2048)).ok_or_else(||oom(budget,"System candidate directory overflow"))?).map_err(|m|oom(budget,m))?;}let indices=candidates.entry(ty.clone()).or_default();if !budget.row(indices){return Err(oom(budget,"System candidate rows denied"))}indices.push(index);}selectors.push((name.clone(),types));}
 if !selectors.is_empty(){let complete=pages.for_each(&mut|_,views|{let file_budget=views.allocation_budget(budget);check(file_budget,poll)?;let code=views.code()?;let cap=selectors.len().checked_mul(4).and_then(|n|n.checked_add(4)).ok_or_else(||oom(file_budget,"System selection overflow"))?;file_budget.charge(cap).map_err(|m|oom(file_budget,m))?;let mut selected=Vec::new();selected.try_reserve_exact(selectors.len()).map_err(|e|Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,e)))?;if selected.capacity()>cap{return Err(oom(file_budget,"System selection exposed excess"))}for(name,types)in &selectors{check(file_budget,poll)?;selected.push(crate::system_accessors_policy::file_mentions_system_with_types(&code.text,name,types));}if !selected.iter().any(|yes|*yes){return Ok(true)}let clean=views.clean(budget)?;crate::raw_type_vars_policy::visit_with(clean,&mut Native{budget:file_budget,poll},&mut|ty,var|{if let Some(indices)=candidates.get(ty){for &index in indices{if selected[index]{if let Some(found)=requested.get_mut(&selectors[index].0).and_then(|vars|vars.get_mut(var)){*found=true}}}}Ok(())})?;Ok(true)})?;if !complete{return Err("System field traversal stopped before exhaustion".into())}}
 let mut builder=Builder::captured(definitions,Arc::clone(budget));for marker in &rows.markers{builder.push_checked(&marker.rel,marker.line,&marker.args,|system,var|requested.get(system).and_then(|vars|vars.get(var)).copied().unwrap_or(false),&mut||check(budget,poll))?;}
 let mut output=builder.finish_with(&mut||check(budget,poll))?;check(budget,poll)?;root.charge(retained(&output).ok_or_else(||oom(root,"System output capacity overflow"))?).map_err(|m|oom(root,m))?;let owned=output.move_owned_data();drop(output);Ok(owned)
 })();let result=match result{Err(Failure::Operational(actual))=>Err(Failure::Operational(actual)),other if budget.denied()=>{drop(other);Err(oom(budget,"System accessor operation denied"))},other=>{check(budget,poll)?;other}};scratch.ok=result.is_ok();drop(scratch);if matches!(&result,Err(Failure::Operational(_))){return result}check(root,poll)?;result
}

#[cfg(test)]#[path="system_accessors_frozen_original.rs"]mod original_system;
#[cfg(test)]mod tests{use super::*;use super::original_system as original;use crate::captured_raw_file::{File,RawPolicyViews};use std::cell::Cell;
struct Pages{file:File,fail:Cell<bool>,stop:Cell<bool>}impl RawPolicyPages for Pages{fn for_each(&self,visit:&mut dyn FnMut(&str,RawPolicyViews<'_>)->Result<bool,Failure>)->Result<bool,Failure>{let keep=self.file.with_policy_views(visit)?;if self.fail.get(){return Err(Failure::Operational(io::Error::from_raw_os_error(1450)))}Ok(keep&&!self.stop.get())}}
const SOURCE:&str="/*\nSYSTEM_DEF(clock)\n*/\nSYSTEM_ACCESSOR(clock, get_value, nameof(value), /datum)\nSYSTEM_ACCESSOR(clock, get_value, nameof(value))\nSYSTEM_ACCESSOR(clock, bad, value)\n/datum/system/clock\n    var/value\n";
fn fixture()->Pages{let root=std::env::current_dir().unwrap().join("system-page-data");Pages{file:File::capture(&root,&root.join("code/a.dm"),SOURCE.to_owned().into()).unwrap(),fail:Cell::new(false),stop:Cell::new(false)}}
#[test]fn system_pages_match_complete_frozen_original_output_and_ordered_diagnostics_including_raw_commented_def(){let pages=fixture();let budget=Budget::new(16*1024*1024).unwrap();let before=budget.used();let output=generate_from_pages(&pages,&HashMap::new(),&budget,&||Ok(())).unwrap();assert_eq!(budget.used()-before,retained(&output).unwrap()+std::mem::size_of::<Budget>()+2*std::mem::size_of::<usize>(),"only funded output and existing fixed scratch metadata may remain");let defs=original::system_defs(SOURCE).into_iter().collect();let mut old=original::Builder::new(defs);for(line,args)in [(4,vec!["clock","get_value","nameof(value)","/datum"]),(5,vec!["clock","get_value","nameof(value)"]),(6,vec!["clock","bad","value"]) ]{old.push("code/a.dm",line,&args.into_iter().map(str::to_owned).collect::<Vec<_>>(),|system,var|system=="clock"&&var=="value");}let old=old.finish();assert_eq!(output.body,old.body);assert_eq!(output.diags,old.diags);assert_eq!(output.diags.len(),2);assert!(output.body.contains("return SSclock?.value"));assert!(output.body.contains("/proc/get_value() as /datum"));}
#[test]fn system_pages_preserve_actual_io_stopped_and_quota_before_later_cancel_then_recover(){let pages=fixture();pages.fail.set(true);assert!(matches!(generate_from_pages(&pages,&HashMap::new(),&Budget::new(16*1024*1024).unwrap(),&||Ok(())),Err(Failure::Operational(ref error))if error.raw_os_error()==Some(1450)));pages.fail.set(false);pages.stop.set(true);assert!(matches!(generate_from_pages(&pages,&HashMap::new(),&Budget::new(16*1024*1024).unwrap(),&||Ok(())),Err(Failure::Unsupported(_))));pages.stop.set(false);let tiny=Budget::new(4096).unwrap();assert!(matches!(generate_from_pages(&pages,&HashMap::new(),&tiny,&||if tiny.denied(){Err(io::ErrorKind::Interrupted.into())}else{Ok(())}),Err(Failure::Operational(ref error))if error.kind()==io::ErrorKind::OutOfMemory));assert!(!generate_from_pages(&pages,&HashMap::new(),&Budget::new(16*1024*1024).unwrap(),&||Ok(())).unwrap().body.is_empty());}
#[test]fn system_original_def_matcher_returns_actual_operational_callback_error_without_string_transport(){let mut seen=Vec::new();let error=crate::system_accessors_policy::visit_system_defs_using("SYSTEM_DEF(a)\nSYSTEM_DEF(b)\n",&mut||Ok::<(),Failure>(()),&mut|_|Ok(()),&mut|name|{seen.push(name.to_owned());Err(Failure::Operational(io::Error::from_raw_os_error(1450)))}).unwrap_err();assert!(matches!(error,Failure::Operational(ref e)if e.raw_os_error()==Some(1450)));assert_eq!(seen,vec!["a"]);let mut names=Vec::new();crate::system_accessors_policy::visit_system_defs_using("SYSTEM_DEF(a)\nSYSTEM_DEF(b)\n",&mut||Ok::<(),Failure>(()),&mut|_|Ok(()),&mut|name|{names.push(name.to_owned());Ok(())}).unwrap();assert_eq!(names,vec!["a","b"]);}
}
